require __DIR__ . '/_bootstrap.php';global $db;$uid=api_require_user();if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')json_err('method','POST required',405);$x=(int)($_POST['x']??0);$y=(int)($_POST['y']??0);$squadId=(int)($_POST['squad']??0);if($x<1||$x>50||$y<1||$y>50)json_err('bad_tile','That is off the map.');$squad=zv2_squad($uid,$squadId);if($squad['id']!==$squadId&&$squadId>0)json_err('bad_squad','Choose one of your squads.');if($squad['traveling'])json_err('already_traveling',$squad['name'].' is already moving.');if($squad['x']===$x&&$squad['y']===$y)json_err('already_here',$squad['name'].' is already here.');
$fog=$db->query("SELECT data FROM discovered WHERE userid=$uid")->fetch_assoc()['data'];$seen=fn(int$a,int$b)=>$a>=1&&$a<=50&&$b>=1&&$b<=50&&substr($fog,($a-1)+($b-1)*50,1)==='1';$known=$seen($x,$y);if(!$known&&!($seen($x+1,$y)||$seen($x-1,$y)||$seen($x,$y+1)||$seen($x,$y-1)))json_err('too_far','New territory must touch explored ground.');
$crew=[];$r=$db->query("SELECT s.id FROM squad_members m JOIN survivors s ON s.id=m.survivor_id LEFT JOIN training_jobs t ON t.survivor_id=s.id WHERE m.squad_id=".$squad['id']." AND s.userid=$uid AND s.job_facility IS NULL AND t.survivor_id IS NULL AND s.hp>0 AND s.fatigue<90 ORDER BY s.id");while($r&&($v=$r->fetch_assoc()))$crew[]=(int)$v['id'];if(!$crew)json_err('no_crew',$squad['name'].' has no healthy, rested members ready to travel.');$distance=abs($squad['x']-$x)+abs($squad['y']-$y);$travel=zv2_tech_effects($uid)['travel_speed']??0;$duration=max(3,(int)ceil($distance*5/(1+$travel/100)));$started=time();$arrives=$started+$duration;$db->query("UPDATE squads SET target_x=$x,target_y=$y,started_at=$started,arrives_at=$arrives,last_event='' WHERE id=".$squad['id']." AND userid=$uid");json_out(['ok'=>true,'squadId'=>$squad['id'],'travel'=>['from'=>['x'=>$squad['x'],'y'=>$squad['y']],'to'=>['x'=>$x,'y'=>$y],'startedAt'=>$started,'arrivesAt'=>$arrives,'seconds'=>$duration,'discovering'=>!$known,'crew'=>$crew],'message'=>$squad['name'].($known?' moving to known territory.':' expedition underway. Territory will be revealed on arrival.')]);
